/// The SPL Token `transfer` instruction that `spl_transfer_assets_from_vault`
/// issues, lifted out of the wrapper so a rule can build and inspect it
/// without issuing the CPI. The account parameters keep the wrapper's own
/// order: `vault_assets` is the wrapper's first account parameter and
/// `user_assets` its second.
pub fn build_transfer_assets_from_vault_ix(
    amount: u64,
    vault_assets: &solana_program::pubkey::Pubkey,
    user_assets: &solana_program::pubkey::Pubkey,
    spl_token_program: &solana_program::pubkey::Pubkey,
) -> Result<solana_program::instruction::Instruction, ProgramError> {
    spl_token::instruction::transfer(
        spl_token_program,
        vault_assets,
        user_assets,
        vault_assets,
        &[],
        amount,
    )
}
